package main

import "fmt"

func SumTo(n int) (int, error) {
	if n < 0 {
		return 0, fmt.Errorf("n 不能为负数")
	}
	total := 0
	for i := 1; i <= n; i++ {
		total += i
	}
	return total, nil
}

func Average(scores []int) (float64, error) {
	if len(scores) == 0 {
		return 0, fmt.Errorf("没有分数")
	}
	total := 0
	for index, score := range scores {
		if score < 0 || score > 100 {
			return 0, fmt.Errorf("第 %d 个分数越界", index+1)
		}
		total += score
	}
	// 已先拒绝空输入；除法之前分别转换，保留1、2这类输入的0.5小数部分。
	return float64(total) / float64(len(scores)), nil
}

func main() {
	var count int
	var ready bool
	var title string
	fmt.Printf("零值：%d %t %q\n", count, ready, title)
	for _, n := range []int{3, 0, -1} {
		value, err := SumTo(n)
		if err != nil {
			fmt.Printf("SumTo(%d)：%v\n", n, err)
			continue
		}
		fmt.Printf("SumTo(%d)=%d\n", n, value)
	}
	for _, scores := range [][]int{{60, 80}, {0}, {}, {101}} {
		value, err := Average(scores)
		if err != nil {
			fmt.Printf("Average(%v)：%v\n", scores, err)
			continue
		}
		fmt.Printf("Average(%v)=%.1f\n", scores, value)
	}
	remaining := 3
	for remaining > 0 {
		remaining--
	}
	fmt.Println("条件循环剩余：", remaining)
	total := 10
	if true {
		total := 20
		fmt.Println("内层：", total)
	}
	fmt.Println("外层：", total)
}

package main

import (
	"fmt"
	"sort"
	"strings"
	"unicode/utf8"
)

func main() {
	a := []int{1, 2, 3}
	// 取片只改变可见范围，b仍与a共享前两个整数。
	b := a[:2]
	b[0] = 9
	c := make([]int, len(a))
	copy(c, a)
	c[0] = 7
	fmt.Println("共享：", a, b)
	fmt.Println("复制：", a, c)
	counts := make(map[string]int)
	for _, word := range strings.Fields("Go go WEB") {
		counts[strings.ToLower(word)]++
	}
	// 从长度0开始追加键；容量仅预留，不能把预留项当真实词名。
	keys := make([]string, 0, len(counts))
	for word := range counts {
		keys = append(keys, word)
	}
	// 先按次数降序，次数相同再按词名；否则map来源的并列顺序不稳定。
	sort.Slice(keys, func(i, j int) bool {
		if counts[keys[i]] != counts[keys[j]] {
			return counts[keys[i]] > counts[keys[j]]
		}
		return keys[i] < keys[j]
	})
	for _, word := range keys {
		fmt.Printf("%s:%d\n", word, counts[word])
	}
	value, exists := counts["rust"]
	fmt.Printf("rust：%d，存在=%t\n", value, exists)
	text := "Go你好"
	fmt.Printf("字节=%d，码点=%d\n", len(text), utf8.RuneCountInString(text))
	for offset, ch := range text {
		fmt.Printf("偏移 %d：%c\n", offset, ch)
	}
}

package main

import (
	"encoding/json"
	"fmt"
)

type Problem struct {
	Title  string `json:"title"`
	Solved bool   `json:"solved"`
	note   string
}

// 值接收者只改这次调用的普通bool字段副本。
func (p Problem) PreviewSolved() { p.Solved = true }
// 指针接收者把修改写回调用者持有的原记录。
func (p *Problem) MarkSolved()   { p.Solved = true }
func (p Problem) Name() string  { return p.Title }

type Namer interface { Name() string }

func Describe(n Namer) string { return "记录：" + n.Name() }

func main() {
	p := Problem{Title: "两数之和", note: "内部备注"}
	p.PreviewSolved()
	fmt.Println("值方法后：", p.Solved)
	p.MarkSolved()
	fmt.Println("指针方法后：", p.Solved)
	data, err := json.Marshal(p)
	if err != nil {
		fmt.Println("编码失败：", err)
		return
	}
	fmt.Println(string(data))
	fmt.Println(Describe(p))
}

package main

import (
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"strings"
	"unicode/utf8"
)

var ErrTitle = errors.New("标题需为 1–40 个码点")

type Input struct { Title string `json:"title"` }

func Parse(raw string) (Input, error) {
	var input Input
	if len(raw) > 256 {
		return input, errors.New("输入超过 256 字节")
	}
	dec := json.NewDecoder(strings.NewReader(raw))
	dec.DisallowUnknownFields()
	if err := dec.Decode(&input); err != nil {
		return Input{}, fmt.Errorf("解析：%w", err)
	}
	var extra any
	// 只有EOF证明尾部结束；第二个值或坏尾部都不能当作正常结束。
	if err := dec.Decode(&extra); !errors.Is(err, io.EOF) {
		return Input{}, errors.New("只允许一个 JSON 值")
	}
	input.Title = strings.TrimSpace(input.Title)
	n := utf8.RuneCountInString(input.Title)
	if n < 1 || n > 40 {
		return Input{}, fmt.Errorf("校验：%w", ErrTitle)
	}
	return input, nil
}

func main() {
	for _, raw := range []string{
		`{"title":"  练习  "}`,
		`{"title":"   "}`,
		`{"title":"练习","owner_id":1}`,
		`{"title":"a"} {"title":"b"}`,
		`{title:练习}`,
	} {
		input, err := Parse(raw)
		if err != nil {
			fmt.Printf("拒绝：%s；标题错误=%t\n", raw, errors.Is(err, ErrTitle))
			continue
		}
		fmt.Println("接受：", input.Title)
	}
}

