package main

import (
	"fmt"
	"os"
	"sort"
	"strconv"
)

type Problem struct { ID int; Created int; Title string }

func page(items []Problem, limit, offset int) ([]Problem, error) {
	if limit < 1 || limit > 100 || offset < 0 { return nil, fmt.Errorf("分页参数非法") }
	// 先复制元素再排序，避免分页调用改变调用者的原始顺序。
	copyItems := append([]Problem(nil), items...)
	sort.Slice(copyItems, func(i, j int) bool {
		if copyItems[i].Created != copyItems[j].Created { return copyItems[i].Created > copyItems[j].Created }
		return copyItems[i].ID > copyItems[j].ID
	})
	if offset >= len(copyItems) { return []Problem{}, nil }
	end := offset + limit
	if end < offset || end > len(copyItems) { end = len(copyItems) }
	return copyItems[offset:end], nil
}

func main() {
	limit := 2
	// 只在未提供时默认；明确的空字符串也应进入解析并拒绝。
	if raw, provided := os.LookupEnv("PAGE_LIMIT"); provided {
		n, err := strconv.Atoi(raw)
		if err != nil || n < 1 || n > 100 { fmt.Println("配置错误：PAGE_LIMIT 需为 1–100"); return }
		limit = n
	}
	items := []Problem{{1, 10, "旧记录"}, {2, 20, "新记录A"}, {3, 20, "新记录B"}}
	first, err := page(items, limit, 0)
	if err != nil { fmt.Println(err); return }
	fmt.Println("第一页：", first)
	empty, _ := page(items, limit, 99)
	fmt.Println("超出末页：", len(empty))
	_, err = page(items, 0, 0)
	fmt.Println("拒绝非法 limit：", err != nil)
}

package main

import (
	"errors"
	"fmt"
	"time"
)

var ErrDenied = errors.New("无权访问")

type Problem struct { ID, OwnerID int; Title string }
type Session struct { UserID int; Expires time.Time; Revoked bool }

func UserFromVerifiedSession(s Session, now time.Time) (int, error) {
	if s.UserID <= 0 || s.Revoked || !now.Before(s.Expires) {
		return 0, errors.New("会话无效")
	}
	return s.UserID, nil
}

func Rename(p *Problem, verifiedUserID int, title string) error {
	// 先验证可信身份与对象归属，再修改；拒绝时原标题必须保持不变。
	if verifiedUserID <= 0 || p.OwnerID != verifiedUserID { return ErrDenied }
	p.Title = title
	return nil
}

func main() {
	p := Problem{1, 10, "A 的题目"}
	err := Rename(&p, 20, "B 篡改")
	fmt.Println("B 被拒绝：", errors.Is(err, ErrDenied))
	fmt.Println("原内容：", p.Title)
	err = Rename(&p, 10, "A 更新")
	fmt.Println("A 更新成功：", err == nil)
	fmt.Println("新内容：", p.Title)
	now := time.Date(2026, 1, 1, 0, 0, 0, 0, time.UTC)
	s := Session{10, now.Add(time.Hour), false}
	userID, err := UserFromVerifiedSession(s, now)
	fmt.Printf("有效会话：user=%d，成功=%t\n", userID, err == nil)
	s.Revoked = true
	_, err = UserFromVerifiedSession(s, now)
	fmt.Println("注销后拒绝：", err != nil)
	s.Revoked = false
	_, err = UserFromVerifiedSession(s, now.Add(time.Hour))
	fmt.Println("到期时拒绝：", err != nil)
}

package main

import (
	"context"
	"fmt"
	"sync"
	"time"
)

func Wait(ctx context.Context, delay time.Duration) error {
	// 先拒绝已取消操作；不让就绪的零时长timer和取消随机竞争。
	if err := ctx.Err(); err != nil { return err }
	timer := time.NewTimer(delay)
	defer timer.Stop()
	select {
	case <-ctx.Done(): return ctx.Err()
	case <-timer.C: return nil
	}
}

func main() {
	var wg sync.WaitGroup
	var mu sync.Mutex
	total := 0
	for worker := 0; worker < 3; worker++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			for i := 0; i < 200; i++ {
				// 同一把锁覆盖读、加一、写回，WaitGroup只负责最后等待完成。
				mu.Lock()
				total++
				mu.Unlock()
			}
		}()
	}
	wg.Wait()
	fmt.Println("安全计数：", total)
	ctx, cancel := context.WithCancel(context.Background())
	cancel()
	fmt.Println("提前取消：", Wait(ctx, time.Hour))
	fmt.Println("正常完成：", Wait(context.Background(), 0) == nil)
}

package main

import (
	"context"
	"errors"
	"fmt"
	"net/http"
	"os"
	"os/signal"
	"strconv"
	"syscall"
	"time"
)

func main() {
	port := "8080"
	// 变量存在但为空也是明确配置，后面的Atoi会拒绝；仅缺失时用8080。
	if raw, provided := os.LookupEnv("PORT"); provided { port = raw }
	n, err := strconv.Atoi(port)
	if err != nil || n < 1 || n > 65535 { fmt.Fprintln(os.Stderr, "PORT 需为 1–65535"); os.Exit(1) }
	if len(os.Args) < 2 || os.Args[1] != "serve" {
		fmt.Println("配置有效：端口", port)
		fmt.Println("启动：go run . serve；验收：GET /health")
		return
	}
	mux := http.NewServeMux()
	mux.HandleFunc("/health", func(w http.ResponseWriter, r *http.Request) {
		if r.URL.Path != "/health" { http.NotFound(w, r); return }
		if r.Method != http.MethodGet { w.WriteHeader(http.StatusMethodNotAllowed); return }
		w.Header().Set("Content-Type", "application/json")
		fmt.Fprintln(w, `{"status":"ok"}`)
	})
	server := &http.Server{
		Addr: ":" + port, Handler: mux,
		ReadHeaderTimeout: 5*time.Second,
		WriteTimeout: 10*time.Second,
		IdleTimeout: 30*time.Second,
	}
	ctx, stop := signal.NotifyContext(context.Background(), os.Interrupt, syscall.SIGTERM)
	defer stop()
	finished := make(chan error, 1)
	go func() { finished <- server.ListenAndServe() }()
	fmt.Println("服务已请求启动，监听端口", port)
	select {
	case err := <-finished:
		if err != nil && !errors.Is(err, http.ErrServerClosed) { fmt.Fprintln(os.Stderr, err); os.Exit(1) }
	case <-ctx.Done():
		// 信号ctx已取消，退出等待必须使用独立父级，才能真正留出5秒预算。
		shutdownCtx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
		defer cancel()
		if err := server.Shutdown(shutdownCtx); err != nil {
			fmt.Fprintln(os.Stderr, "优雅退出超时：", err)
			_ = server.Close()
		}
		if err := <-finished; err != nil && !errors.Is(err, http.ErrServerClosed) { fmt.Fprintln(os.Stderr, err) }
		fmt.Println("服务已停止")
	}
}
